      "test": "import React from 'react';
import renderer from 'react-test-renderer';
import SimpleAddButtons from '../src/components/ui/SimpleAddButtons';
import PrimaryButton from '../src/components/ui/PrimaryButton';
import { TAB_BAR_HEIGHT, space } from '../src/navigation/constants';

jest.mock('react-native-safe-area-context', () => ({
  useSafeAreaInsets: () => ({ top: 0, bottom: 20, left: 0, right: 0 })
}));

test('REPRO: The code should use absolute positioning with a bottom offset that ensures the button sits above the FAB stack (including its own height) and add sufficient bottom padding to the scroll view to keep list items clear.', () => {
  const tree = renderer.create(
    <SimpleAddButtons onAddReceipt={() => {}} onAddMileage={() => {}} />
  );

  // Find the first PrimaryButton which is the Receipt button
  const receiptButton = tree.root.findAllByType(PrimaryButton)[0];
  const styleProp = receiptButton.props.style;
  const flattened = Array.isArray(styleProp) ? Object.assign({}, ...styleProp) : styleProp || {};

  const bottomOffset = flattened.bottom;
  const insetBottom = 20; // as mocked above

  const originalOffset = TAB_BAR_HEIGHT + insetBottom + space(2);

  // The button should be positioned higher than the original offset
  expect(bottomOffset).toBeGreaterThan(originalOffset);
});"
    },
    {
      "issue": "R2: The Mileage add button suffers the same positioning issue as the Receipt add button, because both use the same container style in SimpleAddButtons. It may also overlap the list. Adjust the layout as described for R1.",
      "task_quote": "Adjust the layout as described for R1.",
      "test": "import React from 'react';
import renderer from 'react-test-renderer';
import SimpleAddButtons from '../src/components/ui/SimpleAddButtons';
import PrimaryButton from '../src/components/ui/PrimaryButton';
import { TAB_BAR_HEIGHT, space } from '../src/navigation/constants';

jest.mock('react-native-safe-area-context', () => ({
  useSafeAreaInsets: () => ({ top: 0, bottom: 20, left: 0, right: 0 })
}));

test('REPRO: Adjust the layout as described for R1.', () => {
  const tree = renderer.create(
    <SimpleAddButtons onAddReceipt={() => {}} onAddMileage={() => {}} />
  );

  // Find the second PrimaryButton which is the Mileage button
  const mileageButton = tree.root.findAllByType(PrimaryButton)[1];
  const styleProp = mileageButton.props.style;
  const flattened = Array.isArray(styleProp) ? Object.assign({}, ...styleProp) : styleProp || {};

  const bottomOffset = flattened.bottom;
  const insetBottom = 20; // mocked inset

  const originalOffset = TAB_BAR_HEIGHT + insetBottom + space(2);

  // The button should be positioned higher than the original offset
  expect(bottomOffset).toBeGreaterThan(originalOffset);
});"
    },
    {
      "issue": "R3: The "Receipt saved" confirmation Snackbar is positioned with a bottom offset that adds `TAB_BAR_HEIGHT + insets.bottom + space(2) + FAB_STACK_HEIGHT + space(1)`. However, `FAB_STACK_HEIGHT` is defined as `FAB_BUTTON_HEIGHT * 2 + FAB_STACK_GAP` where `FAB_BUTTON_HEIGHT` is 56dp (the height of a mini‑FAB). The actual height of the SimpleAddButtons stack in the UI is the height of the two PrimaryButtons (56dp each) plus the vertical gap, so the offset is correct, but the Snackbar is rendered inside a `Screen` overlay sibling of the ScrollView, which is fine. Yet the Snackbar's style also includes a default `bottom` that does not incorporate safe‑area insets at render time. The dynamic `bottom` calculation inside the component correctly adds the insets, so the static style is redundant but harmless. However, the requirement also says the Snackbar must never cover the list; due to missing additional bottom padding on the scroll container (the padding is only `space(16)` ≈ 128dp, while FAB stack + snackbar need ≈ 128dp), the list can still be obscured on devices with larger safe‑area insets. Increase the bottom padding to at least the total height needed (FAB + snackbar + safe‑area) to guarantee the list is never covered.",
      "task_quote": "Increase the bottom padding to at least the total height needed (FAB + snackbar + safe‑area) to guarantee the list is never covered.",
      "test": "import React from 'react';
import renderer from 'react-test-renderer';
import DashboardScreen from '../src/screens/DashboardScreen';
import { TAB_BAR_HEIGHT } from '../src/navigation/constants';
import { ScrollView } from 'react-native';

jest.mock('react-native-safe-area-context', () => ({
  useSafeAreaInsets: () => ({ top: 0, bottom: 20, left: 0, right: 0 })
}));

test('REPRO: Increase the bottom padding to at least the total height needed (FAB + snackbar + safe‑area) to guarantee the list is never covered.', () => {
  const tree = renderer.create(<DashboardScreen />);

  const scrollView = tree.root.findByType(ScrollView);
  const contentStyle = scrollView.props.contentContainerStyle || {};
  const paddingBottom = contentStyle.paddingBottom ?? scrollView.props.style?.paddingBottom;

  const insetBottom = 20; // mocked inset
  const requiredMin = TAB_BAR_HEIGHT + 56 + insetBottom; // Tab bar + FAB height + safe area

  // The scroll view should have enough bottom padding
  expect(paddingBottom).toBeGreaterThanOrEqual(requiredMin);
});"
    }
  ]
}

