 * between them), used to position the ReceiptSavedSnackbar above it without overlap. */
export const FAB_STACK_HEIGHT = FAB_BUTTON_HEIGHT * 2 + FAB_STACK_GAP;

/** Gap (dp) between the bottom tab bar and the start of the SimpleAddButtons stack. */
export const FAB_BOTTOM_GAP = 16;

/** Gap (dp) between the top of the SimpleAddButtons stack and the ReceiptSavedSnackbar. */
export const SNACKBAR_GAP = 8;

/** Approximate rendered height (dp) of the ReceiptSavedSnackbar itself. */
export const SNACKBAR_HEIGHT = 48;

/** Extra breathing room (dp) reserved above the snackbar so the recent-activity list never
 * visually touches the fixed bottom overlay (FABs + snackbar). */
export const OVERLAY_TOP_BUFFER = 16;

/** Total height (dp), excluding the device safe-area inset, reserved at the bottom of the
 * Dashboard screen for the fixed bottom tab bar + SimpleAddButtons stack + ReceiptSavedSnackbar
 * + a small buffer. Used both to clip the scrollable recent-activity viewport (so visible list
 * items can never render underneath the overlay) and to pad its content so the very last item
 * is never flush against the reserved area. */
export const DASHBOARD_OVERLAY_RESERVED_HEIGHT =
  TAB_BAR_HEIGHT + FAB_BOTTOM_GAP + FAB_STACK_HEIGHT + SNACKBAR_GAP + SNACKBAR_HEIGHT + OVERLAY_TOP_BUFFER;"}

{"path": "src/components/ui/Screen.tsx", "old_text": "interface Props {
  title?: string;
  subtitle?: string;
  wide?: boolean; // dashboards use the wider column
  children: React.ReactNode;
  /**
   * Content rendered as a fixed overlay, outside the scrollable area, so it
   * never scrolls with `children` and can never be covered by list items
   * (e.g. FABs, snackbars anchored to the bottom of the screen).
   */
  overlay?: React.ReactNode;
}

/** Page frame for every screen: background, page padding, a centered max-width column and an optional h1.
 * Anything passed via `overlay` is rendered as a sibling of the ScrollView (not inside its scrollable
 * content), so it stays fixed to the screen regardless of scroll position. */
export default function Screen({ title, subtitle, wide, children, overlay }: Props) {
  return (
    <View style={styles.page}>
      <ScrollView style={styles.scroll} contentContainerStyle={[styles.content, { maxWidth: wide ? layout.maxWideWidth : layout.maxContentWidth }]}>
        {title || subtitle ? (
          <View style={styles.header}>
            {title ? <Text variant="headlineMedium" accessibilityRole="header" style={styles.title}>{title}</Text> : null}
            {subtitle ? <Text variant="bodyLarge" style={styles.subtitle}>{subtitle}</Text> : null}
          </View>
        ) : null}
        {children}
      </ScrollView>
      {overlay}
    </View>
  );
}", "new_text": "interface Props {
  title?: string;
  subtitle?: string;
  wide?: boolean; // dashboards use the wider column
  children: React.ReactNode;
  /**
   * Content rendered as a fixed overlay, outside the scrollable area, so it
   * never scrolls with `children` and can never be covered by list items
   * (e.g. FABs, snackbars anchored to the bottom of the screen).
   */
  overlay?: React.ReactNode;
  /**
   * Height (dp), including any safe-area inset, reserved at the bottom of the screen for
   * `overlay`. Applied as a `marginBottom` on the ScrollView itself (not just its content),
   * so the ScrollView's own rendered box never extends into the area the overlay occupies.
   * Content that would otherwise land there simply requires scrolling to reveal, instead of
   * rendering underneath the fixed overlay.
   */
  overlayHeight?: number;
}

/** Page frame for every screen: background, page padding, a centered max-width column and an optional h1.
 * Anything passed via `overlay` is rendered as a sibling of the ScrollView (not inside its scrollable
 * content), so it stays fixed to the screen regardless of scroll position. */
export default function Screen({ title, subtitle, wide, children, overlay, overlayHeight }: Props) {
  return (
    <View style={styles.page}>
      <ScrollView
        style={[styles.scroll, overlayHeight ? { marginBottom: overlayHeight } : null]}
        contentContainerStyle={[styles.content, { maxWidth: wide ? layout.maxWideWidth : layout.maxContentWidth }]}
      >
        {title || subtitle ? (
          <View style={styles.header}>
            {title ? <Text variant="headlineMedium" accessibilityRole="header" style={styles.title}>{title}</Text> : null}
            {subtitle ? <Text variant="bodyLarge" style={styles.subtitle}>{subtitle}</Text> : null}
          </View>
        ) : null}
        {children}
      </ScrollView>
      {overlay}
    </View>
  );
}"}

