import React from 'react';
import renderer from 'react-test-renderer';
import Navigation from '../src/navigation';

test('REPRO: R6 not verified: The implementation of the bottom tab bar (likely in src/navigation/index.tsx) does not ensure the tab labels are fully visible on a 390x844 screen. The current bottom navigation may truncate or hide labels on small screens because its configuration does not set a fixed height of 56dp or adjust label text size. Verify that BottomNavigation is configured with label visibility (e.g., \'always\') and that the tab bar height accommodates the labels without clipping.', () => {
  // Render the navigation component.
  const testRenderer = renderer.create(<Navigation />);
  const root = testRenderer.root;

  // Find any component that has labelVisibility prop set to 'always'.
  const labelVisibilityNodes = root.findAll(
    node => node.props && node.props.labelVisibility === 'always'
  );
  expect(labelVisibilityNodes.length).toBeGreaterThan(0);

  // Find any component that defines a style or barStyle with a height >= 56.
  const heightNodes = root.findAll(node => {
    const style = node.props?.style || node.props?.barStyle;
    if (!style) return false;
    const extractHeight = s => {
      if (Array.isArray(s)) {
        for (const item of s) {
          const h = extractHeight(item);
          if (typeof h === 'number') return h;
        }
      } else if (typeof s === 'object' && s !== null) {
        if (typeof s.height === 'number') return s.height;
      }
      return undefined;
    };
    const height = extractHeight(style);
    return typeof height === 'number' && height >= 56;
  });
  expect(heightNodes.length).toBeGreaterThan(0);
});"
